package com.delivery.platform.catalog.branch.api;
import com.delivery.platform.catalog.common.CatalogSupport;import com.delivery.platform.identity.security.IdentityPrincipal;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.math.*;import java.util.*;
@RestController public class BranchController {private final JdbcClient db;private final CatalogSupport support;public BranchController(JdbcClient d,CatalogSupport s){db=d;support=s;}public record Branch(UUID id,UUID merchantId,String code,String name,String addressLine,String district,String phone,String status,String timezone,BigDecimal latitude,BigDecimal longitude){}public record Save(@NotBlank String code,@NotBlank String name,@NotBlank String addressLine,String district,String phone,@NotBlank String timezone,@DecimalMin("-90")@DecimalMax("90")BigDecimal latitude,@DecimalMin("-180")@DecimalMax("180")BigDecimal longitude){}public record Status(@Pattern(regexp="ACTIVE|INACTIVE|TEMPORARILY_CLOSED")String status){}
 @GetMapping("/api/v1/merchants/{merchantId}/branches") @PreAuthorize("hasAuthority('CATALOG_BRANCHES_VIEW')") List<Branch> list(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID merchantId){support.merchant(p,merchantId);return db.sql("select * from branches where tenant_id=:t and merchant_id=:m order by name").param("t",p.tenantId()).param("m",merchantId).query((r,n)->map(r)).list();}
 @PostMapping("/api/v1/merchants/{merchantId}/branches") @Transactional @PreAuthorize("hasAuthority('CATALOG_BRANCHES_CREATE')") Branch create(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID merchantId,@Valid @RequestBody Save q){support.merchant(p,merchantId);UUID id=UUID.randomUUID();db.sql("insert into branches(id,tenant_id,merchant_id,code,name,address_line,district,phone,timezone,latitude,longitude) values(:i,:t,:m,lower(:c),:n,:a,:d,:p,:z,:la,:lo)").param("i",id).param("t",p.tenantId()).param("m",merchantId).param("c",q.code()).param("n",q.name()).param("a",q.addressLine()).param("d",q.district()).param("p",q.phone()).param("z",q.timezone()).param("la",q.latitude()).param("lo",q.longitude()).update();support.audit(p,"BRANCH_CREATED","BRANCH",id);return one(p,id);}
 @GetMapping("/api/v1/branches/{id}") @PreAuthorize("hasAuthority('CATALOG_BRANCHES_VIEW')") Branch one(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id){support.branch(p,id);return db.sql("select * from branches where id=:i").param("i",id).query((r,n)->map(r)).single();}
 @PutMapping("/api/v1/branches/{id}") @Transactional @PreAuthorize("hasAuthority('CATALOG_BRANCHES_UPDATE')") Branch update(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id,@Valid @RequestBody Save q){support.branch(p,id);db.sql("update branches set code=lower(:c),name=:n,address_line=:a,district=:d,phone=:p,timezone=:z,latitude=:la,longitude=:lo,updated_at=now() where id=:i").param("c",q.code()).param("n",q.name()).param("a",q.addressLine()).param("d",q.district()).param("p",q.phone()).param("z",q.timezone()).param("la",q.latitude()).param("lo",q.longitude()).param("i",id).update();support.audit(p,"BRANCH_UPDATED","BRANCH",id);return one(p,id);}
 @PatchMapping("/api/v1/branches/{id}/status") @Transactional @PreAuthorize("hasAuthority('CATALOG_BRANCHES_DISABLE')") Branch status(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id,@Valid @RequestBody Status q){support.branch(p,id);db.sql("update branches set status=:s,updated_at=now() where id=:i").param("s",q.status()).param("i",id).update();support.audit(p,"BRANCH_STATUS_CHANGED","BRANCH",id);return one(p,id);}private Branch map(java.sql.ResultSet r)throws java.sql.SQLException{return new Branch(r.getObject("id",UUID.class),r.getObject("merchant_id",UUID.class),r.getString("code"),r.getString("name"),r.getString("address_line"),r.getString("district"),r.getString("phone"),r.getString("status"),r.getString("timezone"),r.getBigDecimal("latitude"),r.getBigDecimal("longitude"));}}
